import React from 'react';
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, Legend
} from 'recharts';
import { useTranslation } from 'react-i18next';

export default function BarChartComponent({ data, date, province, foodTypes }) {
  const { t } = useTranslation();
  if (!data.length || !province) return null;

  // Define distinct colors for each food type
  const foodTypeColors = {
    'Bread': '#8884d8',
    'Milk': '#82ca9d',
    'Eggs': '#ffc658'
  };

  const chartData = foodTypes.map(foodType => {
    const pt = data.find(d => d.date === date && d.province === province && d.type === foodType);
    return { 
      foodType, 
      foodTypeTranslated: t(`food_types.${foodType}`),
      value: pt ? pt.value : 0 
    };
  });

  // Check if we have any data for this date
  const hasDataForDate = chartData.some(item => item.value > 0);

  if (!hasDataForDate) {
    return (
      <div>
        <h2>{t('bar_chart_title', { date, province })}</h2>
        <p style={{ textAlign: 'center', color: '#666', marginTop: '50px' }}>
          No data available for {date} in {province}
        </p>
      </div>
    );
  }

  return (
    <div>
      <h2>{t('bar_chart_title', { date, province })}</h2>
      <BarChart width={700} height={300} data={chartData}>
        <CartesianGrid strokeDasharray="3 3" />
        <XAxis dataKey="foodType" />
        <YAxis 
          domain={['dataMin - 0.5', 'dataMax + 0.5']}
          tickFormatter={(value) => value.toFixed(1)}
        />
        <Tooltip 
          formatter={(value, name) => [`$${value.toFixed(2)}`, name]}
          labelFormatter={(label) => `${label}`}
        />
        <Legend />
        <Bar 
          dataKey="value" 
          fill={(entry) => foodTypeColors[entry.foodType] || '#8884d8'}
        />
      </BarChart>
    </div>
  );
}
